  insert into public.t3a_d1_content_version(content_object_id, version_no, approval_status, operational_state, body) select content_object_id, 'v2.0', 'drafting', 'not_loaded'::public.t3a_operational_state, '{"stage": 3, "title": "THE COMPLAINT AND THE TWO ACCOUNTS", "source_digest": "08177b3f9f85f4f4d3548c66de6104c04f75f1928234b5e8a2ffaf1cf3bbf39c", "brief_summary": "The participant reads the brief in the pack and submits the work the submission instructions name.", "participant_pack": [{"document": "D1", "title": "The brief", "text": "You coordinate a program in which two team members from different functions must continue working together. One has raised a written complaint about the other''s conduct with the people function; the people function has confirmed receipt and told you the process is running and that you should not investigate. What the record shows: the two are jointly named on a deliverable due in three weeks; the people function''s process has no stated completion date; the deliverable requires them to exchange work twice in that period; the people function has said working arrangements are yours to set; and neither party has asked you to change anything."}], "submission_instructions": "Produce the position you would put about the working arrangement; what you would ask each party and the people function; what you would propose and what you would move on; and what would be agreed, recorded and taken forward. The work is submitted within 3 days.", "question_applicability": [{"question": "Q-D5-01", "state": "DIRECT", "basis": "Three positions, three enquiries, three shared items, four options — all confined to the working arrangement"}, {"question": "Q-D5-01b", "state": "CONDITIONAL", "basis": "Served once its parent records a serving answer"}, {"question": "Q-D5-02", "state": "DIRECT", "basis": "Three positions, three enquiries, three shared items, four options — all confined to the working arrangement"}, {"question": "Q-D5-02b", "state": "CONDITIONA