  insert into public.t3a_content_object(identifier, family, title, dimension_id, current_operational_state) select 'SRC-D5-S4-010', 'source'::public.t3a_content_family, 'THE TEAM PUT BACK TOGETHER', 'D5', 'not_loaded'::public.t3a_operational_state
