  insert into public.t3a_d1_content_version(content_object_id, version_no, approval_status, operational_state, body) select content_object_id, 'v2.0', 'drafting', 'not_loaded'::public.t3a_operational_state, '{"stage": 4, "title": "THE TEAM PUT BACK TOGETHER", "source_digest": "baf14f871e894d284c721fe9a74ba16da0d26c582ea3bcf6ce495704126899e6", "mentor_brief": "The facilitator facilitates the session and observes the observed participant only. At B1 the facilitator states the speaking order aloud: the three co-participants, then the observed participant. During the B2 round the facilitator does not look at, gesture towards or address the observed participant. The facilitator reads the scripted text verbatim, reacts to nothing, and does not press, repeat or escalate, whatever the observed participant says or does not say. The facilitator makes no note of how anything was said and forms no view of any co-participant. The co-participants are role players; nothing they say is recorded, and nothing they say designates a position, an enquiry, a shared item, an option or a route.", "participant_pre_brief": "A team is being reconstituted after a period in which it was split across two programs. You hold a workstream in the reconstituted team. What the record shows: five members return from two different programs; each program used different reporting practices, both documented; the reconstituted team has one deliverable due in eight weeks; no working arrangement has been set; and the team lead has asked the members to propose one within a week.", "script": [{"beat": "B1", "type": "SAY", "spoken": "We have one item today. I will go round in the order on your cards, the three of you first, then you. Two minutes each.", "direction": null, "capture": []}, {"beat": "B2", "type": "ROUND", "spoken": "Over to you, in the order I gave.", "direction": "Invite the three co-participants in the stated order. Do not address the observed participant.", "capture": [{"set": "C1", "state": "open"}, {"set": "C1b", "state": "open"}, {"set": "C2", "state": "open"}, {"set": "C2b", "state": "open"}, {"set": "C3", "state": "open"}, {"set": "C3b", "state": "open"}, {"set": "C4", "state": "open"}, {"set": "C4b", "state": "open"}, {"set": "C5", "state": "open"}, {"set": "C5b", "state": "open"}, {"set": "C6", "state": "open"}, {"set": "C6b", "state": "open"}, {"set": "C7", "state": "open"}, {"set": "C7b", "state": "open"}, {"set": "C8", "state": "open"}]}, {"beat": "B3", "type": "ASK", "spoken": "Where do you stand on the working arrangement?", "direction": "Read once, verbatim.", "capture": [{"set": "C1", "state": "update"}, {"set": "C1b", "state": "update"}, {"set": "C2", "state": "update"}, {"set": "C2b", "state": "update"}, {"set": "C3", "state": "update"}, {"set": "C3b", "state": "update"}]}, {"beat": "B4", "type": "ASK", "spoken": "What are you putting forward, and what would you move on?", "direction": "Read once, verbatim.", "capture": [{"set": "C4", "state": "update"}, {"set": "C4b", "state": "update"}, {"set": "C5", "state": "update"}, {"set": "C5b", "state": "update"}]}, {"beat": "B5", "type": "ASK", "spoken": "What would be agreed in the week, and what if it is not?", "direction": "Read once, verbatim.", "capture": [{"set": "C6", "state": "update"}, {"set": "C6b", "state": "update"}, {"set": "C7", "state": "update"}, {"set": "C7b", "state": "update"}, {"set": "C8", "state": "update"}]}, {"beat": "B6", "type": "ASK", "spoken": "Just so the position is right — you said the lead had already set the arrangement. Had they?", "direction": "Read once, verbatim.", "capture": [{"set": "C9", "state": "open"}]}, {"beat": "B7", "type": "SAY", "spoken": "That is the session. Thank you all.", "direction": "End the session.", "capture": [{"set": "C1", "state": "final"}, {"set": "C2", "state": "final"}, {"set": "C3", "state": "final"}, {"set": "C4", "state": "final"}, {"set": "C5", "state": "final"}, {"set": "C6", "state": "final"}, {"set": "C7", "state": "final"}, {"set": "C8", "state": "final"}, {"set": "C9", "state": "final"}]}], "co_participant_positions": [{"Co-participant": "CP-1", "Position stated at the round": "State the reporting practice from one program."}, {"Co-participant": "CP-2", "Position stated at the round": "State the reporting practice from the other."}, {"Co-participant": "CP-3", "Position stated at the round": "As the team lead, state the one-week point and the eight-week deliverable."}], "impact_assessment": [{"Part": "1. Shared material", "Finding": "Only the scripted situation is placed before the group, and it names no real organization", "Controls": "IA-01 shown in one shared window holding only the shared material"}, {"Part": "2. Identity", "Finding": "The observed participant is the authenticated participant; the three co-participants are role players", "Controls": "IA-02 platform account authentication; role players are never observed"}, {"Part": "3. Recording", "Finding": "Nothing is recorded", "Controls": "IA-03 no media persists"}, {"Part": "4. Correction", "Finding": "A correction reaches only the observed participant''s record", "Controls": "IA-04 a correction reaches only the observed participant''s record"}, {"Part": "5. Withdrawal", "Finding": "Withdrawal removes the participant''s determinations from composition only", "Controls": "IA-05 withdrawal excludes from composition; history retained"}, {"Part": "6. Group composition", "Finding": "One observed participant, three role players and one facilitator", "Controls": "IA-06 composition record and confidentiality undertaking from each role player"}, {"Part": "7. Accommodation", "Finding": "An accommodation is settled before composition and never changes the observation during the session", "Controls": "IA-07 settled before composition"}], "impact_result": "Completed", "question_applicability": [{"question": "Q-D5-01", "state": "DIRECT", "basis": "Three positions, three enquiries, three shared items, four options"}, {"question": "Q-D5-01b", "state": "CONDITIONAL", "basis": "Served once its parent records a serving answer"}, {"question": "Q-D5-02", "state": "DIRECT", "basis": "Three positions, three enquiries, three shared items, four options"}, {"question": "Q-D5-02b", "state": "CONDITIONAL", "basis": "Served once its parent records a serving answer"}, {"question": "Q-D5-03", "state": "DIRECT", "basis": "Three positions, three enquiries, three shared items, four options"}, {"question": "Q-D5-03b", "state": "CONDITIONAL", "basis": "Served once its parent records a serving answer"}, {"question": "Q-D5-04", "state": "DIRECT", "basis": "Three positions, three enquiries, three shared items, four options"}, {"question": "Q-D5-04b", "state": "CONDITIONAL", "basis": "Served once its parent records a serving answer"}, {"question": "Q-D5-05", "state": "DIRECT", "basis": "Three positions, three enquiries, three shared items, four options"}, {"question": "Q-D5-05b", "state": "CONDITIONAL", "basis": "Served once its parent records a serving answer"}, {"question": "Q-D5-06", "state": "DIRECT", "basis": "In play on this source"}, {"question": "Q-D5-06b", "state": "CONDITIONAL", "basis": "Served once its parent records a serving answer"}, {"question": "Q-D5-07", "state": "DIRECT", "basis": "In play on this source"}, {"question": "Q-D5-07b", "state": "CONDITIONAL", "basis": "Served once its parent records a serving answer"}, {"question": "Q-D5-08", "state": "DIRECT", "basis": "The one-week point is the persistence point"}, {"question": "Q-D5-09", "state": "DIRECT", "basis": "In play on this source"}], "material_map": [{"Item": "SI1", "Item text": "both documented practices", "Where the participant meets it": "The pre-brief", "Quoted text": "each program used different reporting practices, both documented"}, {"Item": "SI2", "Item text": "the one-week proposal point", "Where the participant meets it": "The pre-brief", "Quoted text": "propose one within a week"}, {"Item": "SI3", "Item text": "the eight-week deliverable, common to all", "Where the participant meets it": "The pre-brief", "Quoted text": "one deliverable due in eight weeks"}], "source_sheet": {"d5_situation_class": "SC-D5-6", "workplace_demand": "Forming one working arrangement for a reconstituted team whose returning members used different documented reporting practices.", "relevant_conduct": "The position stated as the participant''s own; whether the other position was asked about; which shared items were named; what was proposed; what change to the participant''s own position was stated; which route was used; whether an agreement and its recording were stated; what was stated about the difference continuing; what was stated when the participant''s own part was put back.", "irrelevant_conduct": "The members'' program histories, never recorded.", "stated_standard": null, "stated_standard_source_quote_or_location": null, "cross_context_map": null, "serving_eligible": false, "recurrence_eligible": true, "replacement_required": false, "name_clearance_status": "CLEARED", "name_clearance_basis": "Controlled role and entity labels only; no real person or organization is named, and no counterpart is named.", "sensitivity_flag": null, "permitted_administration_variance": "Pronunciation only; accommodations affecting turn order or response window are recorded and set timing_not_comparable.", "unsupported_inferences": "That either practice is better; that proposing early is leadership; anything about team building.", "compatibility_class": "S4-GROUP-ROUND", "designated_positions": [{"id": "DP1", "text": "one of the two documented practices adopted whole"}, {"id": "DP2", "text": "a new practice drafted from both"}, {"id": "DP3", "text": "each workstream keeps its own practice for the first deliverable"}], "designated_enquiries": [{"id": "DE1", "text": "what each practice requires and at what cadence"}, {"id": "DE2", "text": "what the eight-week deliverable needs from reporting"}, {"id": "DE3", "text": "what the lead expects at the one-week point"}], "shared_items": [{"id": "SI1", "text": "both documented practices"}, {"id": "SI2", "text": "the one-week proposal point"}, {"id": "SI3", "text": "the eight-week deliverable, common to all"}], "available_options": [{"id": "AO1", "text": "one practice adopted whole"}, {"id": "AO2", "text": "a drafted practice"}, {"id": "AO3", "text": "parallel practices for this deliverable"}, {"id": "AO4", "text": "the decision is taken by the lead"}], "available_routes": [{"id": "AR1", "text": "this session"}], "agreement_contents": [{"id": "AC1", "text": "the practice"}, {"id": "AC2", "text": "the cadence"}, {"id": "AC3", "text": "what goes to the lead"}], "counterpart_role": "The returning members and the team lead.", "counterpart_position": "Two documented practices.", "difference_established": "Two documented practices and no working arrangement.", "authority_relation": "The lead has asked the members to propose.", "recording_route": "The circulated proposal.", "persistence_point": "The one-week point.", "exchange_test_point": "B6", "list_note": "Not selectable in available_routes, because only the session itself completes and is evidenced inside the session; a route the participant can only state is an intention: a written proposal circulated to the team; to the team lead.", "source_note": null, "situation_class_label": "A working relationship to be formed where none exists", "observation_mode_label": "group_session", "min_seconds": 900, "max_seconds": 1500}, "source_identifier": "SRC-D5-S4-010", "stage_code": "S4", "source_version_hash": "baf14f871e894d284c721fe9a74ba16da0d26c582ea3bcf6ce495704126899e6", "serving_eligible": false, "verbatim": "", "rewording": {"register": "CR-314", "authority": "Tony Mofoke written delegation of 23 October 2026 (CR-219)", "rule": "D5-69 (CR-232): the counterpart role label is not the subject of a verb in a bound family item", "family": "available_options", "item": "AO4", "before": "the lead decides", "after": "the decision is taken by the lead", "package_source_digest": "21ce72582695a6c65a9489132424f52cafd0c2e26298e1bddde9bbcfaed9e533"}}'::jsonb from public.t3a_content_object o
    where o.identifier = 'SRC-D5-S4-010' and o.family = 'source'::public.t3a_content_family and not exists (select 1 from public.t3a_d1_content_version v where v.content_object_id = o.content_object_id);
  -- the counterpart load guard returns null for a refused source, and the insert then writes nothing: fail loudly rather than load four of five
  if not exists (select 1 from public.t3a_d1_content_version v join public.t3a_content_object o using (content_object_id) where o.identifier = 'SRC-D5-S4-010' and o.family = 'source'::public.t3a_content_family) then
